                if (host.equalsIgnoreCase("localhost") ||
                    host.equalsIgnoreCase("127.0.0.1") ||
                    host.equalsIgnoreCase("0.0.0.0") ||
                    host.endsWith(".local") ||
                    host.endsWith(".internal")) {
                    return false;
                }
                // Resolve hostname to IP and check if it's private
                try {
                    InetAddress address = InetAddress.getByName(host);
                    String ip = address.getHostAddress();
                    // Check if the resolved IP is private
                    if (isIpAddress(ip)) {
                        for (String prefix : PRIVATE_IP_PREFIXES) {
                            if (ip.startsWith(prefix)) {
                                return false;
                            }
                        }
                        if (ip.startsWith("fe80:") || ip.startsWith("fc00:") || ip.startsWith("fd00:")) {
                            return false;
                        }
                    }
                } catch (UnknownHostException e) {
                    // If host cannot be resolved, treat as invalid
                    return false;
                }
                return true;
            }
        } catch (MalformedURLException e) {
            // Invalid URL - treat as invalid
            return false;
        }
    }

